const money = (value: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(value || 0)
const date = (value: string) => new Intl.DateTimeFormat('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date(value))
const compact = (value: number) => new Intl.NumberFormat('vi-VN').format(value)
const messageOf = (error: unknown) => error instanceof Error ? error.message : 'Có lỗi xảy ra. Vui lòng thử lại.'
const statusName: Record<OrderStatus, string> = { pending: 'Chờ xác nhận', confirmed: 'Đã xác nhận', shipping: 'Đang giao', completed: 'Hoàn thành', cancelled: 'Đã hủy' }
const productStatusName: Record<Product['status'], string> = { draft: 'Bản nháp', published: 'Đang hiển thị', hidden: 'Đã ẩn' }

type Toast = { id: number; text: string; kind: 'success' | 'error' }
const ToastContext = createContext<(text: string, kind?: Toast['kind']) => void>(() => {})
function useToast() { return useContext(ToastContext) }
function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([])
  const toast = (text: string, kind: Toast['kind'] = 'success') => {
    const id = Date.now() + Math.random()
    setToasts((current) => [...current, { id, text, kind }])
    window.setTimeout(() => setToasts((current) => current.filter((item) => item.id !== id)), 4300)
  }
  return <ToastContext.Provider value={toast}>{children}<div className="admin-toasts" aria-live="polite"><AnimatePresence>{toasts.map((item) => <motion.div key={item.id} className={`admin-toast ${item.kind}`} initial={{ opacity: 0, y: 14, scale: .96 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, x: 24 }}>{item.kind === 'success' ? <Check size={17} /> : <AlertCircle size={17} />}{item.text}</motion.div>)}</AnimatePresence></div></ToastContext.Provider>
}
function Loading({ label = 'Đang tải dữ liệu...' }: { label?: string }) { return <div className="admin-loading"><Loader2 size={24} className="admin-spin" /><span>{label}</span></div> }
function Empty({ title, detail, action }: { title: string; detail?: string; action?: ReactNode }) { return <div className="admin-empty"><span className="admin-empty-icon"><Package size={26} /></span><h3>{title}</h3>{detail && <p>{detail}</p>}{action}</div> }
function ErrorBox({ error, retry }: { error: string; retry?: () => void }) { return <div className="admin-error"><AlertCircle size={20} /><span>{error}</span>{retry && <button className="admin-text-button" onClick={retry}>Thử lại</button>}</div> }
function PageHead({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="admin-page-head"><div><span className="admin-eyebrow">{eyebrow || 'MUSE CONTROL ROOM'}</span><h1>{title}</h1>{description && <p>{description}</p>}</div>{action && <div className="admin-page-action">{action}</div>}</div> }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="admin-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label> }
function Metric({ icon, label, value, note, tone }: { icon: ReactNode; label: string; value: string; note?: string; tone?: string }) { return <motion.div className={`admin-metric ${tone || ''}`} initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .35 }}><div className="admin-metric-top"><span className="admin-metric-icon">{icon}</span><ArrowUpRight size={17} /></div><span className="admin-metric-label">{label}</span><strong>{value}</strong>{note && <small>{note}</small>}</motion.div> }

function AdminGate() {
  const [allowed, setAllowed] = useState<boolean | null>(null)
  const location = useLocation()
  useEffect(() => { let live = true; if (!isSupabaseConfigured) { setAllowed(false); return }; getCurrentAdmin().then((ok) => { if (live) setAllowed(ok) }).catch(() => { if (live) setAllowed(false) }); return () => { live = false } }, [])
  if (allowed === null) return <div className="admin-gate"><Loading label="Đang xác thực quyền quản trị..." /></div>
  if (!allowed) return <Navigate to="/admin/login" replace state={{ from: location.pathname }} />
  return <Outlet />
}
function LoginPage() {
  const navigate = useNavigate(); const location = useLocation()
  const [email, setEmail] = useState(''); const [password, setPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false); const [busy, setBusy] = useState(false)
  const [checking, setChecking] = useState(isSupabaseConfigured); const [error, setError] = useState('')
  useEffect(() => { if (!isSupabaseConfigured) return; let live = true; getCurrentAdmin().then((ok) => { if (live && ok) navigate('/admin', { replace: true }) }).catch((err) => { if (live) setError(messageOf(err)) }).finally(() => { if (live) setChecking(false) }); return () => { live = false } }, [navigate])
  async function submit(event: FormEvent) { event.preventDefault(); setError(''); setBusy(true); try { await signInAdmin(email.trim(), password); const next = (location.state as { from?: string } | null)?.from || '/admin'; navigate(next.startsWith('/admin') && next !== '/admin/login' ? next : '/admin', { replace: true }) } catch (err) { setError(messageOf(err)) } finally { setBusy(false) } }
  if (checking) return <div className="admin-gate"><Loading label="Đang kiểm tra phiên đăng nhập..." /></div>
  return <div className="admin-login"><div className="admin-login-art"><div className="admin-login-image" /><div className="admin-login-brand"><Link to="/" aria-label="MUSE STORE trang chủ">MUSE<span>STORE</span></Link><span>THE NEW PERSPECTIVE</span></div><div className="admin-login-quote"><span>CURATED WITH INTENTION</span><h2>Every detail<br /><em>is an expression.</em></h2><p>Không gian quản trị dành riêng cho những lựa chọn đẹp.</p></div><span className="admin-login-art-index">01 / 01</span></div><div className="admin-login-panel"><div className="admin-login-panel-top"><Link to="/" className="admin-login-back"><ArrowLeft size={16} /> Quay lại cửa hàng</Link><Link to="/" className="admin-mobile-logo">MUSE<span>STORE</span></Link><span>ADMIN PORTAL</span></div><motion.div className="admin-login-form-wrap" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .5 }}><span className="admin-eyebrow">MUSE STORE · MANAGEMENT</span><h1>Chào mừng<br /><em>trở lại.</em></h1><p>Đăng nhập để quản lý cửa hàng của bạn.</p>{!isSupabaseConfigured ? <div className="admin-setup-note"><CircleHelp size={21} /><div><strong>Chưa kết nối Supabase</strong><span>Thêm VITE_SUPABASE_URL và VITE_SUPABASE_ANON_KEY vào tệp .env.local để bật đăng nhập quản trị.</span></div></div> : <form onSubmit={submit}><Field label="Email quản trị"><input type="email" autoComplete="username" required placeholder="admin@musestore.vn" value={email} onChange={(event) => setEmail(event.target.value)} /></Field><Field label="Mật khẩu"><div className="admin-password"><input type={showPassword ? 'text' : 'password'} autoComplete="current-password" required placeholder="Nhập mật khẩu" value={password} onChange={(event) => setPassword(event.target.value)} /><button type="button" aria-label={showPassword ? 'Ẩn mật khẩu' : 'Hiện mật khẩu'} onClick={() => setShowPassword(!showPassword)}>{showPassword ? <EyeOff size={18} /> : <Eye size={18} />}</button></div></Field>{error && <div className="admin-form-error"><AlertCircle size={17} />{error}</div>}<button className="admin-button admin-button-dark admin-login-submit" type="submit" disabled={busy}>{busy ? <Loader2 size={17} className="admin-spin" /> : <>Đăng nhập hệ thống <ArrowRight size={17} /></>}</button></form>}<div className="admin-login-foot">Chỉ tài khoản được cấp quyền quản trị mới có thể truy cập.</div></motion.div><span className="admin-login-copyright">© {new Date().getFullYear()} MUSE STORE</span></div></div>
}

