function AdminLayout() {
  const navigate = useNavigate(); const location = useLocation(); const toast = useToast()
  const [menuOpen, setMenuOpen] = useState(false); const [loggingOut, setLoggingOut] = useState(false)
  useEffect(() => { setMenuOpen(false) }, [location.pathname])
  const current = [...navGroups.flatMap((group) => group.items)].find((item) => item.to === location.pathname)?.label || (location.pathname.includes('/edit') ? 'Chỉnh sửa sản phẩm' : 'Quản trị')
  async function logout() { setLoggingOut(true); try { await signOutAdmin(); navigate('/admin/login', { replace: true }) } catch (error) { toast(messageOf(error), 'error'); setLoggingOut(false) } }
  return <div className="admin-root">{menuOpen && <button className="admin-sidebar-backdrop" aria-label="Đóng menu" onClick={() => setMenuOpen(false)} />}<aside className={`admin-sidebar ${menuOpen ? 'is-open' : ''}`}><div className="admin-sidebar-top"><Link to="/admin" className="admin-logo">MUSE<span>STORE</span><small>ADMIN STUDIO</small></Link><button className="admin-sidebar-close" onClick={() => setMenuOpen(false)} aria-label="Đóng menu"><X size={20} /></button></div><div className="admin-sidebar-caption">YOUR CREATIVE COMMERCE SPACE</div><nav className="admin-nav">{navGroups.map((group) => <div className="admin-nav-group" key={group.label}><span>{group.label}</span>{group.items.map(({ to, label, icon: Icon }) => <NavLink key={to} end={to === '/admin'} to={to} className={({ isActive }) => `admin-nav-item ${isActive ? 'active' : ''}`}><Icon size={18} strokeWidth={1.7} />{label}{to === '/admin/products/new' && <Plus size={15} className="admin-nav-tail" />}</NavLink>)}</div>)}</nav><div className="admin-sidebar-bottom"><div className="admin-sidebar-help"><Sparkles size={18} /><strong>MUSE STORE</strong><p>Định hình trải nghiệm mua sắm theo cách của bạn.</p><Link to="/" target="_blank">Xem cửa hàng <ArrowUpRight size={14} /></Link></div><button className="admin-logout" onClick={logout} disabled={loggingOut}>{loggingOut ? <Loader2 size={17} className="admin-spin" /> : <LogOut size={17} />}Đăng xuất</button></div></aside><div className="admin-main-shell"><header className="admin-topbar"><div className="admin-topbar-left"><button className="admin-menu-toggle" onClick={() => setMenuOpen(true)} aria-label="Mở menu"><Menu size={21} /></button><span className="admin-topbar-breadcrumb">MUSE ADMIN <ChevronRight size={13} /> <strong>{current}</strong></span></div><div className="admin-topbar-right"><Link to="/" target="_blank" className="admin-view-store">Xem cửa hàng <ExternalLink size={15} /></Link><div className="admin-admin-chip"><span>M</span><div><strong>Administrator</strong><small>Store manager</small></div></div></div></header><main className="admin-content"><AnimatePresence mode="wait"><motion.div key={location.pathname} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -7 }} transition={{ duration: .2 }}><Outlet /></motion.div></AnimatePresence></main></div></div>
}
function ProductThumb({ product }: { product: Product }) { return product.cover_image ? <img className="admin-product-thumb" src={product.cover_image} alt="" /> : <span className="admin-product-thumb placeholder"><ImagePlus size={19} /></span> }
function StatusBadge({ status }: { status: OrderStatus }) { return <span className={`admin-status order-${status}`}>{statusName[status]}</span> }
function ProductBadge({ status }: { status: Product['status'] }) { return <span className={`admin-status product-${status}`}>{productStatusName[status]}</span> }
function DashboardPage() {
  const [stats, setStats] = useState<DashboardStats | null>(null); const [error, setError] = useState(''); const [reload, setReload] = useState(0)
  useEffect(() => { let live = true; getDashboardStats().then((value) => { if (live) setStats(value) }).catch((err) => { if (live) setError(messageOf(err)) }); return () => { live = false } }, [reload])
  if (error) return <><PageHead title="Dashboard" /><ErrorBox error={error} retry={() => { setError(''); setReload((n) => n + 1) }} /></>
  if (!stats) return <><PageHead title="Dashboard" /><Loading /></>
  const maxCount = Math.max(1, ...stats.categoryCounts.map((entry) => entry.count))
  return <><PageHead eyebrow="TỔNG QUAN CỬA HÀNG" title="Dashboard" description="Một góc nhìn rõ ràng về cửa hàng của bạn." action={<button className="admin-button admin-button-light" onClick={() => { setStats(null); setReload((n) => n + 1) }}><RefreshCw size={16} /> Làm mới</button>} /><div className="admin-dashboard-hero"><div><span>GOOD DAY AT MUSE</span><h2>Ý tưởng đẹp<br /><em>bắt đầu từ đây.</em></h2><p>Quản lý sản phẩm, theo dõi đơn hàng và hoàn thiện câu chuyện thương hiệu.</p><Link to="/admin/products/new" className="admin-button admin-button-cream">Thêm sản phẩm mới <ArrowUpRight size={17} /></Link></div><div className="admin-hero-orbit"><span>M</span></div><span className="admin-hero-count">MUSE / STUDIO 01</span></div><div className="admin-metrics"><Metric icon={<Package size={21} />} label="Tổng sản phẩm" value={compact(stats.totalProducts)} note="Tất cả trạng thái" /><Metric icon={<ShoppingBag size={21} />} label="Thời trang" value={compact(stats.fashionProducts)} tone="nude" /><Metric icon={<Sparkles size={21} />} label="Mỹ phẩm" value={compact(stats.beautyProducts)} tone="sand" /><Metric icon={<ClipboardList size={21} />} label="Tổng đơn hàng" value={compact(stats.totalOrders)} tone="dark" /></div><div className="admin-dashboard-grid"><section className="admin-panel admin-category-chart"><div className="admin-section-head"><div><span className="admin-eyebrow">PRODUCT MIX</span><h2>Sản phẩm theo danh mục</h2></div><Link to="/admin/categories" className="admin-text-link">Xem danh mục <ArrowRight size={15} /></Link></div>{stats.categoryCounts.length ? <div className="admin-chart-bars">{stats.categoryCounts.map(({ category, count }) => <div className="admin-chart-row" key={category.id}><div><span>{category.name}</span><strong>{count}</strong></div><div className="admin-chart-track"><motion.span initial={{ width: 0 }} animate={{ width: `${count / maxCount * 100}%` }} transition={{ duration: .7 }} /></div></div>)}</div> : <Empty title="Chưa có danh mục" detail="Thêm danh mục để bắt đầu phân loại sản phẩm." action={<Link to="/admin/categories" className="admin-button admin-button-light">Thêm danh mục</Link>} />}</section><section className="admin-panel admin-stock-panel"><div className="admin-section-head"><div><span className="admin-eyebrow">INVENTORY WATCH</span><h2>Sắp hết hàng</h2></div><Link to="/admin/inventory" className="admin-text-link">Tồn kho <ArrowRight size={15} /></Link></div>{stats.lowStockProducts.length ? <div className="admin-compact-list">{stats.lowStockProducts.slice(0, 5).map((product) => <div key={product.id} className="admin-compact-row"><ProductThumb product={product} /><div><strong>{product.name}</strong><small>{product.sku}</small></div><span className={`admin-stock-count ${product.stock === 0 ? 'zero' : ''}`}>{product.stock} còn</span></div>)}</div> : <Empty title="Tồn kho ổn định" detail="Chưa có sản phẩm nào sắp hết hàng." />}</section></div><div className="admin-dashboard-grid bottom"><section className="admin-panel"><div className="admin-section-head"><div><span className="admin-eyebrow">JUST ADDED</span><h2>Sản phẩm mới</h2></div><Link to="/admin/products" className="admin-text-link">Tất cả <ArrowRight size={15} /></Link></div>{stats.latestProducts.length ? <div className="admin-compact-list">{stats.latestProducts.slice(0, 5).map((product) => <Link to={`/admin/products/${product.id}/edit`} key={product.id} className="admin-compact-row"><ProductThumb product={product} /><div><strong>{product.name}</strong><small>{product.sku}</small></div><span className="admin-compact-price">{money(product.price)}</span></Link>)}</div> : <Empty title="Chưa có sản phẩm" action={<Link to="/admin/products/new" className="admin-button admin-button-light">Thêm sản phẩm đầu tiên</Link>} />}</section><section className="admin-panel"><div className="admin-section-head"><div><span className="admin-eyebrow">RECENT ACTIVITY</span><h2>Đơn hàng gần đây</h2></div><Link to="/admin/orders" className="admin-text-link">Tất cả <ArrowRight size={15} /></Link></div>{stats.latestOrders.length ? <div className="admin-compact-list">{stats.latestOrders.slice(0, 5).map((order) => <Link to="/admin/orders" key={order.id} className="admin-compact-row order"><span className="admin-order-mini"><ClipboardList size={19} /></span><div><strong>{order.code}</strong><small>{order.customer_name} · {date(order.created_at)}</small></div><StatusBadge status={order.status} /></Link>)}</div> : <Empty title="Chưa có đơn hàng" detail="Đơn hàng mới sẽ hiển thị tại đây." />}</section></div></>
}

function ProductsPage() {
  const [products, setProducts] = useState<Product[]>([]); const [categories, setCategories] = useState<Category[]>([])
  const [busy, setBusy] = useState(true); const [error, setError] = useState(''); const [search, setSearch] = useState('')
  const [kind, setKind] = useState('all'); const [status, setStatus] = useState('all'); const [categoryId, setCategoryId] = useState('all'); const [reload, setReload] = useState(0)
  const toast = useToast()
  useEffect(() => { let live = true; Promise.all([listAdminProducts(), listCategories()]).then(([p, c]) => { if (live) { setProducts(p); setCategories(c) } }).catch((err) => { if (live) setError(messageOf(err)) }).finally(() => { if (live) setBusy(false) }); return () => { live = false } }, [reload])
  const filtered = useMemo(() => products.filter((product) => { const q = search.trim().toLowerCase(); return (!q || product.name.toLowerCase().includes(q) || product.sku.toLowerCase().includes(q)) && (kind === 'all' || product.kind === kind) && (status === 'all' || product.status === status) && (categoryId === 'all' || product.category_id === categoryId) }), [products, search, kind, status, categoryId])
  async function remove(product: Product) { if (!window.confirm(`Xóa vĩnh viễn “${product.name}”? Thao tác này không thể hoàn tác.`)) return; try { await deleteProduct(product.id); setProducts((current) => current.filter((item) => item.id !== product.id)); toast('Đã xóa sản phẩm.') } catch (err) { toast(messageOf(err), 'error') } }
  async function toggle(product: Product) { try { const updated = await saveProduct({ name: product.name, sku: product.sku, kind: product.kind, price: product.price, status: product.status === 'hidden' ? 'published' : 'hidden' }, product.id); setProducts((current) => current.map((item) => item.id === product.id ? updated : item)); toast(updated.status === 'hidden' ? 'Đã ẩn sản phẩm.' : 'Đã hiển thị sản phẩm.') } catch (err) { toast(messageOf(err), 'error') } }
  return <><PageHead eyebrow="CATALOG MANAGEMENT" title="Sản phẩm" description="Mọi sản phẩm, một không gian quản lý rõ ràng." action={<Link to="/admin/products/new" className="admin-button admin-button-dark"><Plus size={17} /> Thêm sản phẩm</Link>} /><div className="admin-inline-metrics"><span><strong>{products.length}</strong> tổng sản phẩm</span><span><strong>{products.filter((item) => item.status === 'published').length}</strong> đang hiển thị</span><span><strong>{products.filter((item) => item.status === 'draft').length}</strong> bản nháp</span></div><section className="admin-panel admin-table-panel"><div className="admin-filter-row"><div className="admin-search"><Search size={18} /><input aria-label="Tìm sản phẩm" placeholder="Tìm tên hoặc mã sản phẩm..." value={search} onChange={(event) => setSearch(event.target.value)} /></div><select aria-label="Lọc loại" value={kind} onChange={(event) => setKind(event.target.value)}><option value="all">Tất cả loại</option><option value="fashion">Thời trang</option><option value="beauty">Mỹ phẩm</option></select><select aria-label="Lọc danh mục" value={categoryId} onChange={(event) => setCategoryId(event.target.value)}><option value="all">Tất cả danh mục</option>{categories.filter((category) => kind === 'all' || category.kind === kind).map((category) => <option value={category.id} key={category.id}>{category.name}</option>)}</select><select aria-label="Lọc trạng thái" value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">Tất cả trạng thái</option><option value="published">Đang hiển thị</option><option value="draft">Bản nháp</option><option value="hidden">Đã ẩn</option></select></div>{error ? <ErrorBox error={error} retry={() => { setError(''); setBusy(true); setReload((n) => n + 1) }} /> : busy ? <Loading /> : filtered.length ? <div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>SẢN PHẨM</th><th>DANH MỤC</th><th>GIÁ BÁN</th><th>TỒN KHO</th><th>TRẠNG THÁI</th><th aria-label="Thao tác" /></tr></thead><tbody>{filtered.map((product) => <tr key={product.id}><td><div className="admin-product-cell"><ProductThumb product={product} /><div><Link to={`/admin/products/${product.id}/edit`}>{product.name}</Link><small>{product.sku} · {product.brand || (product.kind === 'fashion' ? 'Thời trang' : 'Mỹ phẩm')}</small></div></div></td><td>{product.category?.name || 'Chưa phân loại'}</td><td><strong>{money(product.price)}</strong>{product.original_price && product.original_price > product.price && <small className="admin-old-price">{money(product.original_price)}</small>}</td><td><span className={`admin-stock-value ${product.stock <= 10 ? 'low' : ''}`}>{product.stock}</span></td><td><ProductBadge status={product.status} /></td><td><div className="admin-row-actions"><Link title="Chỉnh sửa" to={`/admin/products/${product.id}/edit`}><Pencil size={17} /></Link><button title={product.status === 'hidden' ? 'Hiện sản phẩm' : 'Ẩn sản phẩm'} onClick={() => toggle(product)}>{product.status === 'hidden' ? <Eye size={17} /> : <EyeOff size={17} />}</button><button title="Xóa" className="danger" onClick={() => remove(product)}><Trash2 size={17} /></button></div></td></tr>)}</tbody></table></div> : <Empty title="Không tìm thấy sản phẩm" detail={products.length ? 'Thử thay đổi bộ lọc hoặc từ khóa tìm kiếm.' : 'Bắt đầu với sản phẩm đầu tiên của MUSE STORE.'} action={!products.length && <Link to="/admin/products/new" className="admin-button admin-button-dark"><Plus size={16} /> Thêm sản phẩm</Link>} />}<div className="admin-table-footer">Hiển thị {filtered.length} / {products.length} sản phẩm</div></section></>
}

const blankProduct: ProductInput = {
  name: '', sku: '', kind: 'fashion', price: 0, original_price: null, stock: 0,
  category_id: null, brand: '', short_description: '', description: '',
  status: 'published', is_new: true, is_featured: false, is_sale: false,
  sizes: [], colors: [], skin_types: [], material: '', fit: '', size_chart: '',
  volume: '', ingredients: '', benefits: '', usage: '',
}
function ProductFormPage() {
  const { id } = useParams(); const editing = Boolean(id); const navigate = useNavigate(); const toast = useToast()
  const [persistedId, setPersistedId] = useState<string | null>(id || null)
  const [form, setForm] = useState<ProductInput>(blankProduct); const [categories, setCategories] = useState<Category[]>([])
  const [existingImages, setExistingImages] = useState<ProductImage[]>([]); const [newImages, setNewImages] = useState<ImageDraft[]>([])
  const [saving, setSaving] = useState(false)
  const [tracked, setTracked] = useState(!editing); const [trackingLocked, setTrackingLocked] = useState(false)
  const [stocks, setStocks] = useState<Record<string, string>>({}); const [expectedUpdatedAt, setExpectedUpdatedAt] = useState('')
  const [loading, setLoading] = useState(editing); const [error, setError] = useState(''); const [preview, setPreview] = useState(false)
  const [uploadMessage, setUploadMessage] = useState('')
  useEffect(() => { let live = true; setPersistedId(id || null); Promise.all([listCategories(), editing ? listAdminProducts() : Promise.resolve([] as Product[])]).then(([cats, products]) => { if (!live) return; setCategories(cats); if (id) { const product = products.find((item) => item.id === id); if (!product) { setError('Không tìm thấy sản phẩm.'); return }; const { category, image_records, variants, sold_count, created_at, updated_at, id: productId, ...fields } = product; setTracked(product.variant_mode === 'tracked'); setTrackingLocked(product.variant_mode === 'tracked'); setExpectedUpdatedAt(product.updated_at); setStocks(Object.fromEntries(variants.filter(item => item.is_active !== false).map(item => [optionKey(item.color, item.size), item.stock === null ? '' : String(item.stock)]))); void category; void sold_count; void created_at; void updated_at; void productId; setForm(fields); setExistingImages(image_records) } }).catch((err) => { if (live) setError(messageOf(err)) }).finally(() => { if (live) setLoading(false) }); return () => { live = false } }, [id, editing])
  function setField(key: keyof ProductInput, value: unknown) { setForm((current) => ({ ...current, [key]: value } as ProductInput)) }
  function changeColors(colors: string[]) {
    setField('colors', colors)
    setExistingImages(items => items.map(image => image.color && !colors.includes(image.color) ? { ...image, color: null, is_color_primary: false } : image))
    setNewImages(items => items.map(image => image.color && !colors.includes(image.color) ? { ...image, color: null, is_color_primary: false } : image))
  }
  async function addFiles(files: FileList | null, color: string | null) {
    if (!files?.length) return
    try {
      const images = Array.from(files)
      if (images.some(file => !['image/jpeg', 'image/png', 'image/webp', 'image/avif'].includes(file.type) || file.size > 10 * 1024 * 1024)) throw new Error('Chỉ hỗ trợ JPG, PNG, WebP hoặc AVIF, tối đa 10 MB mỗi ảnh.')
      if (existingImages.length + newImages.length + images.length > 12) throw new Error('Mỗi sản phẩm có tối đa 12 ảnh.')
      const prepared = await Promise.all(images.map(file => new Promise<ImageDraft>((resolve,reject) => {
        const reader = new FileReader(); reader.onload = () => resolve({ file, preview: String(reader.result), color, is_primary: false, is_color_primary: false }); reader.onerror = () => reject(new Error('Không đọc được ảnh.')); reader.readAsDataURL(file)
      })))
      setNewImages(current => [...current, ...prepared])
    } catch (err) { toast(messageOf(err), 'error') }
  }
  function makePrimary(key: string | number) {
    setExistingImages(items => items.map(image => ({ ...image, is_primary: image.id === key })))
    setNewImages(items => items.map((image,index) => ({ ...image, is_primary: index === key })))
  }
  function makeColorPrimary(key: string | number, color: string) {
    setExistingImages(items => items.map(image => image.color === color ? { ...image, is_color_primary: image.id === key } : image))
    setNewImages(items => items.map((image,index) => image.color === color ? { ...image, is_color_primary: index === key } : image))
  }
  function assignColor(key: string | number, color: string | null) {
    setExistingImages(items => items.map(image => image.id === key ? { ...image, color, is_color_primary: false } : image))
    setNewImages(items => items.map((image,index) => index === key ? { ...image, color, is_color_primary: false } : image))
  }
  async function submit(targetStatus: Product['status']) {
    setError('')
    if (!form.name.trim()) { setError('Vui lòng nhập tên sản phẩm.'); return }
    if (!form.sku.trim()) { setError('Vui lòng nhập mã sản phẩm.'); return }
    if (!Number.isFinite(form.price) || form.price < 0) { setError('Giá bán không hợp lệ.'); return }
    if (!Number.isInteger(form.stock ?? 0) || (form.stock ?? 0) < 0) { setError('Tồn kho phải là số nguyên không âm.'); return }
    if (targetStatus === 'published' && !form.category_id) { setError('Vui lòng chọn danh mục trước khi đăng.'); return }
    if (targetStatus === 'published' && !existingImages.length && !newImages.length) { setError('Vui lòng thêm ít nhất một ảnh trước khi đăng.'); return }
    if (!validateOptions(form.colors ?? []) || !validateOptions(form.sizes ?? [])) { setError('Màu và size không được trùng hoặc để trống.'); return }
    if (existingImages.length + newImages.length > 12) { setError('Mỗi sản phẩm có tối đa 12 ảnh.'); return }
    let variants = null
    try { if (tracked && form.kind === 'fashion') variants = variantMatrix(form.colors ?? [], form.sizes ?? [], stocks) } catch (err) { setError(messageOf(err)); return }
    setSaving(true)
    try {
      let productId = persistedId || id
      let version = expectedUpdatedAt
      if (!productId) {
        const created = await saveProduct({ ...form, status: 'draft' })
        productId = created.id; version = created.updated_at
        setPersistedId(productId); setExpectedUpdatedAt(version)
      }
      let retained = [...existingImages]
      let pending = [...newImages]
      while (pending.length) {
        const draft = pending[0]
        setUploadMessage('Đang tải ảnh lên... Còn ' + pending.length + ' ảnh')
        const [uploaded] = await uploadProductImages([draft.file], productId, true)
        retained = [...retained, { ...uploaded, color: draft.color, is_primary: draft.is_primary, is_color_primary: draft.is_color_primary }]
        setExistingImages(retained)
        pending = pending.slice(1); setNewImages(pending)
      }
      const saved = await saveProductEditor({ ...form, status: targetStatus }, productId, version, variants, retained)
      setExpectedUpdatedAt(saved.updated_at)
      toast(targetStatus === 'draft' ? 'Đã lưu bản nháp.' : targetStatus === 'hidden' ? 'Đã lưu sản phẩm ẩn.' : editing ? 'Đã cập nhật sản phẩm.' : 'Đã đăng sản phẩm lên cửa hàng.')
      navigate('/admin/products')
    } catch (err) { setError(messageOf(err)); toast(messageOf(err), 'error') } finally { setSaving(false); setUploadMessage('') }
  }
  const chosenCategory = categories.filter((item) => item.kind === form.kind)
  const cover = newImages.find(image => image.is_primary)?.preview || existingImages.find(image => image.is_primary)?.url || existingImages[0]?.url || newImages[0]?.preview
  const tracking = tracked && form.kind === 'fashion'
  const totalStock = tracking ? (form.colors?.length ? form.colors : [null]).reduce((sum, color) => sum + (form.sizes?.length ? form.sizes : [null]).reduce((sub, size) => sub + (Number(stocks[optionKey(color, size)]) || 0), 0), 0) : form.stock ?? 0
  if (loading) return <><PageHead title={editing ? 'Chỉnh sửa sản phẩm' : 'Thêm sản phẩm'} /><Loading /></>
  return <><div className="admin-form-nav"><Link to="/admin/products"><ArrowLeft size={17} /> Sản phẩm</Link><span>/</span><strong>{editing ? 'Chỉnh sửa' : 'Thêm mới'}</strong></div><PageHead eyebrow={editing ? 'EDIT PRODUCT' : 'NEW PRODUCT'} title={editing ? 'Chỉnh sửa sản phẩm' : 'Thêm sản phẩm mới'} description="Kể câu chuyện sản phẩm qua từng chi tiết." action={<div className="admin-form-top-actions"><button className="admin-button admin-button-light" onClick={() => setPreview(true)}><Eye size={16} /> Xem trước</button><button className="admin-button admin-button-light" onClick={() => submit('draft')} disabled={saving}><Save size={16} /> Lưu nháp</button><button className="admin-button admin-button-dark" onClick={() => submit(form.status || 'draft')} disabled={saving}>{saving ? <Loader2 size={17} className="admin-spin" /> : <><Check size={17} /> {editing ? 'Lưu thay đổi' : form.status === 'draft' ? 'Lưu nháp' : form.status === 'hidden' ? 'Lưu ẩn' : 'Đăng sản phẩm'}</>}</button></div>} />
    {error && <div className="admin-form-error prominent"><AlertCircle size={18} />{error}</div>}{uploadMessage && <div className="admin-upload-state"><Loader2 size={17} className="admin-spin" />{uploadMessage}</div>}
    <fieldset disabled={saving} className="admin-product-fields"><div className="admin-editor-grid"><div className="admin-editor-main"><section className="admin-panel admin-form-section"><div className="admin-form-section-title"><span>01</span><div><h2>Thông tin cơ bản</h2><p>Những thông tin khách hàng nhìn thấy đầu tiên.</p></div></div><div className="admin-fields-grid"><Field label="Tên sản phẩm *"><input value={form.name} onChange={(e) => setField('name', e.target.value)} placeholder="Ví dụ: Đầm lụa dáng midi" /></Field><Field label="Mã sản phẩm *"><input value={form.sku} onChange={(e) => setField('sku', e.target.value.toUpperCase())} placeholder="MUSE-F001" /></Field><Field label="Loại sản phẩm *"><select disabled={trackingLocked} value={form.kind} onChange={(e) => { setField('kind', e.target.value); setField('category_id', null); setField('sizes', []); changeColors([]) }}><option value="fashion">Thời trang</option><option value="beauty">Mỹ phẩm</option></select></Field><Field label="Danh mục *"><select value={form.category_id || ''} onChange={(e) => setField('category_id', e.target.value || null)}><option value="">Chọn danh mục</option>{chosenCategory.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></Field><Field label="Thương hiệu"><input value={form.brand || ''} onChange={(e) => setField('brand', e.target.value)} placeholder="MUSE STORE" /></Field><Field label={tracking ? "Tổng tồn kho (tự động)" : "Số lượng tồn kho"}><input disabled={tracking} type="number" min="0" step="1" value={totalStock} onChange={(e) => setField('stock', Number(e.target.value))} /></Field><Field label="Giá bán (VNĐ) *"><input type="number" min="0" step="1000" value={form.price || ''} onChange={(e) => setField('price', Number(e.target.value))} placeholder="890000" /></Field><Field label="Giá gốc (VNĐ)"><input type="number" min="0" step="1000" value={form.original_price ?? ''} onChange={(e) => setField('original_price', e.target.value ? Number(e.target.value) : null)} placeholder="1190000" /></Field></div><Field label="Mô tả ngắn"><textarea rows={3} maxLength={300} value={form.short_description || ''} onChange={(e) => setField('short_description', e.target.value)} placeholder="Một câu ngắn gọn về điểm nổi bật của sản phẩm..." /></Field><Field label="Mô tả chi tiết"><textarea rows={6} value={form.description || ''} onChange={(e) => setField('description', e.target.value)} placeholder="Chất liệu, cảm hứng thiết kế, trải nghiệm sử dụng..." /></Field></section>
      <ProductImagesEditor colors={form.kind === 'fashion' ? form.colors ?? [] : []} images={existingImages} drafts={newImages} onFiles={(files,color) => { void addFiles(files,color) }} onRemove={imageId => setExistingImages(items => items.filter(image => image.id !== imageId))} onRemoveDraft={index => setNewImages(items => items.filter((_,i) => i !== index))} onPrimary={makePrimary} onColorPrimary={makeColorPrimary} onColor={assignColor} />
      <section className="admin-panel admin-form-section"><div className="admin-form-section-title"><span>03</span><div><h2>{form.kind === 'fashion' ? 'Chi tiết thời trang' : 'Chi tiết mỹ phẩm'}</h2><p>Thông tin phù hợp với từng loại sản phẩm.</p></div></div>{form.kind === 'fashion' ? <><ProductOptionsEditor colors={form.colors ?? []} sizes={form.sizes ?? []} tracked={tracked} locked={trackingLocked} stocks={stocks} onColors={changeColors} onSizes={values => setField('sizes', values)} onTracked={setTracked} onStock={(key,value) => setStocks(current => ({ ...current, [key]: value }))} /><div className="admin-fields-grid"><Field label="Chất liệu"><input value={form.material || ''} onChange={(e) => setField('material', e.target.value)} placeholder="Lụa satin" /></Field><Field label="Kiểu dáng"><input value={form.fit || ''} onChange={(e) => setField('fit', e.target.value)} placeholder="Dáng suông" /></Field><Field label="Bảng size"><input value={form.size_chart || ''} onChange={(e) => setField('size_chart', e.target.value)} placeholder="S: 82–86 cm..." /></Field></div></> : <><div className="admin-fields-grid"><Field label="Dung tích / Khối lượng"><input value={form.volume || ''} onChange={(e) => setField('volume', e.target.value)} placeholder="30 ml" /></Field><Field label="Loại da phù hợp" hint="Phân cách bằng dấu phẩy"><input value={form.skin_types?.join(', ') || ''} onChange={(e) => setField('skin_types', e.target.value.split(',').map((item) => item.trim()).filter(Boolean))} placeholder="Da khô, Da hỗn hợp" /></Field></div><Field label="Thành phần"><textarea rows={3} value={form.ingredients || ''} onChange={(e) => setField('ingredients', e.target.value)} placeholder="Niacinamide, Hyaluronic Acid..." /></Field><Field label="Công dụng"><textarea rows={3} value={form.benefits || ''} onChange={(e) => setField('benefits', e.target.value)} placeholder="Dưỡng ẩm, làm sáng..." /></Field><Field label="Hướng dẫn sử dụng"><textarea rows={3} value={form.usage || ''} onChange={(e) => setField('usage', e.target.value)} placeholder="Sử dụng sau bước làm sạch..." /></Field></>}</section></div>
      <aside className="admin-editor-side"><section className="admin-panel admin-form-section admin-publish-panel"><div className="admin-form-section-title"><span>04</span><div><h2>Hiển thị</h2><p>Kiểm soát cách sản phẩm xuất hiện.</p></div></div><Field label="Trạng thái"><select value={form.status || 'draft'} onChange={(e) => setField('status', e.target.value)}><option value="draft">Bản nháp</option><option value="published">Đang hiển thị</option><option value="hidden">Ẩn khỏi website</option></select></Field><div className="admin-switch-list"><label><span><strong>Sản phẩm mới</strong><small>Gắn nhãn NEW</small></span><input type="checkbox" checked={Boolean(form.is_new)} onChange={(e) => setField('is_new', e.target.checked)} /></label><label><span><strong>Sản phẩm nổi bật</strong><small>Hiển thị ở khu vực nổi bật</small></span><input type="checkbox" checked={Boolean(form.is_featured)} onChange={(e) => setField('is_featured', e.target.checked)} /></label><label><span><strong>Đang khuyến mãi</strong><small>Đánh dấu ưu đãi</small></span><input type="checkbox" checked={Boolean(form.is_sale)} onChange={(e) => setField('is_sale', e.target.checked)} /></label></div></section><section className="admin-panel admin-preview-card"><span className="admin-eyebrow">LIVE PREVIEW</span>{cover ? <img src={cover} alt="Xem trước sản phẩm" /> : <span className="admin-preview-placeholder"><ImagePlus size={31} /></span>}<div><small>{form.kind === 'fashion' ? 'THỜI TRANG' : 'MỸ PHẨM'}</small><strong>{form.name || 'Tên sản phẩm của bạn'}</strong><span>{money(form.price)}</span></div></section></aside></div>
    </fieldset><div className="admin-form-bottom"><Link to="/admin/products" className="admin-button admin-button-light">Hủy</Link><button className="admin-button admin-button-light" onClick={() => submit('draft')} disabled={saving}>Lưu nháp</button><button className="admin-button admin-button-dark" onClick={() => submit(form.status || 'draft')} disabled={saving}>{saving ? <Loader2 size={17} className="admin-spin" /> : <Check size={17} />}{editing ? 'Lưu thay đổi' : form.status === 'draft' ? 'Lưu nháp' : form.status === 'hidden' ? 'Lưu ẩn' : 'Đăng sản phẩm'}</button></div>
    <AnimatePresence>{preview && <motion.div className="admin-modal-backdrop" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => { if (e.target === e.currentTarget) setPreview(false) }}><motion.div className="admin-modal admin-product-preview-modal" initial={{ scale: .96, y: 15 }} animate={{ scale: 1, y: 0 }} exit={{ scale: .96, y: 15 }}><button className="admin-modal-close" onClick={() => setPreview(false)} aria-label="Đóng"><X size={20} /></button><span className="admin-eyebrow">XEM TRƯỚC SẢN PHẨM</span><div className="admin-preview-modal-grid">{cover ? <img src={cover} alt="Sản phẩm" /> : <div className="admin-preview-placeholder"><ImagePlus size={36} /></div>}<div><small>{form.kind === 'fashion' ? 'THỜI TRANG' : 'MỸ PHẨM'} / {form.sku || 'SKU'}</small><h2>{form.name || 'Tên sản phẩm'}</h2><strong>{money(form.price)}</strong><p>{form.short_description || 'Mô tả ngắn sẽ xuất hiện ở đây.'}</p><span className="admin-status product-draft">Bản xem trước</span></div></div></motion.div></motion.div>}</AnimatePresence>
  </>
}

const slugify = (value: string) => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
function CategoriesPage() {
  const toast = useToast(); const [categories, setCategories] = useState<Category[]>([]); const [products, setProducts] = useState<Product[]>([])
  const [busy, setBusy] = useState(true); const [error, setError] = useState(''); const [open, setOpen] = useState(false)
  const [editing, setEditing] = useState<Category | null>(null); const [form, setForm] = useState<CategoryInput>({ kind: 'fashion', name: '', slug: '', description: '', image_url: '', sort_order: 0 })
  const [imageFile, setImageFile] = useState<File | null>(null); const [imagePreview, setImagePreview] = useState(''); const [saving, setSaving] = useState(false)
  useEffect(() => { let live = true; Promise.all([listCategories(), listAdminProducts()]).then(([c, p]) => { if (live) { setCategories(c); setProducts(p) } }).catch((err) => { if (live) setError(messageOf(err)) }).finally(() => { if (live) setBusy(false) }); return () => { live = false } }, [])
  function showForm(category?: Category) { setEditing(category || null); setForm(category ? { kind: category.kind, name: category.name, slug: category.slug, description: category.description, image_url: category.image_url, sort_order: category.sort_order } : { kind: 'fashion', name: '', slug: '', description: '', image_url: '', sort_order: 0 }); setImageFile(null); setImagePreview(''); setOpen(true) }
  function chooseImage(file?: File) { if (!file) return; if (!file.type.startsWith('image/')) { toast('Vui lòng chọn tệp hình ảnh.', 'error'); return }; setImageFile(file); const reader = new FileReader(); reader.onload = () => setImagePreview(String(reader.result)); reader.readAsDataURL(file) }
  async function submit(event: FormEvent) { event.preventDefault(); setSaving(true); try { const image_url = imageFile ? await uploadCategoryImage(imageFile) : form.image_url; const result = await saveCategory({ ...form, slug: form.slug || slugify(form.name), image_url }, editing?.id); setCategories((current) => [...current.filter((item) => item.id !== result.id), result].sort((a, b) => a.sort_order - b.sort_order)); toast(editing ? 'Đã cập nhật danh mục.' : 'Đã thêm danh mục.'); setOpen(false) } catch (err) { toast(messageOf(err), 'error') } finally { setSaving(false) } }
  async function remove(category: Category) { const count = products.filter((item) => item.category_id === category.id).length; if (count) { toast(`Danh mục đang chứa ${count} sản phẩm. Hãy chuyển sản phẩm trước khi xóa.`, 'error'); return }; if (!window.confirm(`Xóa danh mục “${category.name}”?`)) return; try { await deleteCategory(category.id); setCategories((current) => current.filter((item) => item.id !== category.id)); toast('Đã xóa danh mục.') } catch (err) { toast(messageOf(err), 'error') } }
  return <><PageHead eyebrow="ORGANIZE THE EDIT" title="Danh mục" description="Sắp đặt bộ sưu tập theo cách khách hàng khám phá." action={<button className="admin-button admin-button-dark" onClick={() => showForm()}><Plus size={17} /> Thêm danh mục</button>} />{error ? <ErrorBox error={error} /> : busy ? <Loading /> : categories.length ? <div className="admin-category-grid">{categories.map((category) => <motion.article key={category.id} className="admin-category-card" whileHover={{ y: -4 }}><div className="admin-category-image">{category.image_url ? <img src={category.image_url} alt="" /> : <span><Tags size={28} /></span>}<span>{category.kind === 'fashion' ? 'THỜI TRANG' : 'MỸ PHẨM'}</span></div><div className="admin-category-body"><div><h2>{category.name}</h2><p>{category.description || 'Danh mục sản phẩm'}</p></div><strong>{products.filter((item) => item.category_id === category.id).length} sản phẩm</strong><div className="admin-category-actions"><button onClick={() => showForm(category)}><Pencil size={16} /> Chỉnh sửa</button><button className="danger" onClick={() => remove(category)}><Trash2 size={16} /> Xóa</button></div></div></motion.article>)}</div> : <Empty title="Chưa có danh mục" detail="Tạo danh mục để phân loại sản phẩm thời trang và mỹ phẩm." action={<button className="admin-button admin-button-dark" onClick={() => showForm()}><Plus size={16} /> Thêm danh mục</button>} />}
    <AnimatePresence>{open && <motion.div className="admin-modal-backdrop" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => { if (e.target === e.currentTarget) setOpen(false) }}><motion.div className="admin-modal admin-form-modal" initial={{ scale: .96, y: 15 }} animate={{ scale: 1, y: 0 }} exit={{ scale: .96, y: 15 }}><button className="admin-modal-close" onClick={() => setOpen(false)} aria-label="Đóng"><X size={20} /></button><span className="admin-eyebrow">CATEGORY EDITOR</span><h2>{editing ? 'Chỉnh sửa danh mục' : 'Thêm danh mục mới'}</h2><form onSubmit={submit}><div className="admin-fields-grid"><Field label="Tên danh mục *"><input required value={form.name} onChange={(e) => setForm((current) => ({ ...current, name: e.target.value, slug: editing ? current.slug : slugify(e.target.value) }))} placeholder="Váy & đầm" /></Field><Field label="Loại sản phẩm"><select value={form.kind} onChange={(e) => setForm((current) => ({ ...current, kind: e.target.value as Category['kind'] }))}><option value="fashion">Thời trang</option><option value="beauty">Mỹ phẩm</option></select></Field><Field label="Đường dẫn"><input required value={form.slug} onChange={(e) => setForm((current) => ({ ...current, slug: slugify(e.target.value) }))} placeholder="vay-dam" /></Field><Field label="Thứ tự hiển thị"><input type="number" min="0" value={form.sort_order ?? 0} onChange={(e) => setForm((current) => ({ ...current, sort_order: Number(e.target.value) }))} /></Field></div><Field label="Mô tả"><textarea rows={3} value={form.description || ''} onChange={(e) => setForm((current) => ({ ...current, description: e.target.value }))} /></Field><Field label="Ảnh đại diện"><div className="admin-category-upload">{(imagePreview || form.image_url) ? <img src={imagePreview || form.image_url || ''} alt="Xem trước danh mục" /> : <span><ImagePlus size={23} /></span>}<label><Upload size={16} /> Chọn ảnh<input type="file" accept="image/*" onChange={(e) => chooseImage(e.target.files?.[0])} /></label>{(imagePreview || form.image_url) && <button type="button" onClick={() => { setImageFile(null); setImagePreview(''); setForm((current) => ({ ...current, image_url: null })) }}><X size={16} /> Bỏ ảnh</button>}</div></Field><div className="admin-modal-actions"><button type="button" className="admin-button admin-button-light" onClick={() => setOpen(false)}>Hủy</button><button type="submit" className="admin-button admin-button-dark" disabled={saving}>{saving ? <Loader2 size={16} className="admin-spin" /> : <Save size={16} />} Lưu danh mục</button></div></form></motion.div></motion.div>}</AnimatePresence></>
}

function InventoryPage() {
  const toast = useToast(); const [products, setProducts] = useState<Product[]>([]); const [drafts, setDrafts] = useState<Record<string, number>>({}); const [busy, setBusy] = useState(true); const [error, setError] = useState(''); const [search, setSearch] = useState(''); const [filter, setFilter] = useState('all'); const [savingId, setSavingId] = useState('')
  useEffect(() => { let live = true; listAdminProducts().then((items) => { if (live) setProducts(items) }).catch((err) => { if (live) setError(messageOf(err)) }).finally(() => { if (live) setBusy(false) }); return () => { live = false } }, [])
  const filtered = products.filter((item) => (filter === 'all' || (filter === 'low' && item.stock > 0 && item.stock <= 10) || (filter === 'out' && item.stock === 0)) && (!search || `${item.name} ${item.sku}`.toLowerCase().includes(search.toLowerCase())))
  async function saveStock(product: Product) { const stock = drafts[product.id]; if (!Number.isInteger(stock) || stock < 0) { toast('Số lượng phải là số nguyên không âm.', 'error'); return }; setSavingId(product.id); try { const updated = await saveProduct({ name: product.name, sku: product.sku, kind: product.kind, price: product.price, stock }, product.id); setProducts((current) => current.map((item) => item.id === product.id ? updated : item)); setDrafts((current) => { const next = { ...current }; delete next[product.id]; return next }); toast('Đã cập nhật tồn kho.') } catch (err) { toast(messageOf(err), 'error') } finally { setSavingId('') } }
  return <><PageHead eyebrow="INVENTORY CONTROL" title="Tồn kho" description="Theo dõi số lượng và cập nhật ngay khi có thay đổi." /><div className="admin-inline-metrics"><span><strong>{products.length}</strong> sản phẩm</span><span><strong>{products.filter((item) => item.stock > 0 && item.stock <= 10).length}</strong> sắp hết hàng</span><span><strong>{products.filter((item) => item.stock === 0).length}</strong> hết hàng</span></div><section className="admin-panel admin-table-panel"><div className="admin-filter-row"><div className="admin-search"><Search size={18} /><input aria-label="Tìm sản phẩm trong kho" placeholder="Tìm sản phẩm hoặc mã SKU..." value={search} onChange={(e) => setSearch(e.target.value)} /></div><select value={filter} onChange={(e) => setFilter(e.target.value)} aria-label="Lọc tồn kho"><option value="all">Tất cả sản phẩm</option><option value="low">Sắp hết hàng (1–10)</option><option value="out">Hết hàng (0)</option></select></div>{error ? <ErrorBox error={error} /> : busy ? <Loading /> : filtered.length ? <div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>SẢN PHẨM</th><th>LOẠI</th><th>TÌNH TRẠNG</th><th>SỐ LƯỢNG</th><th aria-label="Lưu" /></tr></thead><tbody>{filtered.map((product) => <tr key={product.id}><td><div className="admin-product-cell"><ProductThumb product={product} /><div><Link to={`/admin/products/${product.id}/edit`}>{product.name}</Link><small>{product.sku}</small></div></div></td><td>{product.kind === 'fashion' ? 'Thời trang' : 'Mỹ phẩm'}</td><td><span className={`admin-status ${product.stock === 0 ? 'stock-out' : product.stock <= 10 ? 'stock-low' : 'stock-good'}`}>{product.stock === 0 ? 'Hết hàng' : product.stock <= 10 ? 'Sắp hết' : 'Còn hàng'}</span></td><td><input className="admin-stock-input" type="number" min="0" step="1" aria-label={`Tồn kho ${product.name}`} disabled={product.variant_mode === 'tracked'} value={drafts[product.id] ?? product.stock} onChange={(e) => setDrafts((current) => ({ ...current, [product.id]: Number(e.target.value) }))} /></td><td>{product.variant_mode === 'tracked' ? <Link className="admin-button admin-button-light admin-small-button" to={`/admin/products/${product.id}/edit`}>Sửa màu–size</Link> : <button className="admin-button admin-button-light admin-small-button" disabled={drafts[product.id] === undefined || savingId === product.id} onClick={() => saveStock(product)}>{savingId === product.id ? <Loader2 size={15} className="admin-spin" /> : <Save size={15} />} Lưu</button>}</td></tr>)}</tbody></table></div> : <Empty title="Không có sản phẩm phù hợp" detail="Thử tìm kiếm hoặc đổi bộ lọc tồn kho." />}<div className="admin-table-footer">Hiển thị {filtered.length} / {products.length} sản phẩm</div></section></>
}

function OrdersPage() {
  const toast = useToast(); const [orders, setOrders] = useState<Order[]>([]); const [busy, setBusy] = useState(true)
  const [error, setError] = useState(''); const [search, setSearch] = useState(''); const [status, setStatus] = useState('all')
  const [selectedId, setSelectedId] = useState<string | null>(null); const [savingId, setSavingId] = useState('')
  useEffect(() => { let live = true; listOrders().then((items) => { if (live) setOrders(items) }).catch((err) => { if (live) setError(messageOf(err)) }).finally(() => { if (live) setBusy(false) }); return () => { live = false } }, [])
  const filtered = orders.filter((order) => (status === 'all' || order.status === status) && (!search || `${order.code} ${order.customer_name} ${order.phone}`.toLowerCase().includes(search.toLowerCase())))
  const selected = orders.find((order) => order.id === selectedId)
  async function changeStatus(order: Order, next: OrderStatus) { if (next === order.status) return; setSavingId(order.id); try { await updateOrderStatus(order.id, next); setOrders((current) => current.map((item) => item.id === order.id ? { ...item, status: next } : item)); toast(`Đã cập nhật đơn ${order.code}: ${statusName[next]}.`) } catch (err) { toast(messageOf(err), 'error') } finally { setSavingId('') } }
  return <><PageHead eyebrow="ORDER MANAGEMENT" title="Đơn hàng" description="Theo dõi hành trình từ xác nhận đến giao tận tay khách hàng." /><div className="admin-inline-metrics"><span><strong>{orders.length}</strong> tổng đơn</span><span><strong>{orders.filter((item) => item.status === 'pending').length}</strong> chờ xác nhận</span><span><strong>{orders.filter((item) => item.status === 'shipping').length}</strong> đang giao</span></div><section className="admin-panel admin-table-panel"><div className="admin-filter-row"><div className="admin-search"><Search size={18} /><input aria-label="Tìm đơn hàng" placeholder="Tìm mã đơn, tên hoặc số điện thoại..." value={search} onChange={(e) => setSearch(e.target.value)} /></div><select aria-label="Lọc trạng thái đơn" value={status} onChange={(e) => setStatus(e.target.value)}><option value="all">Tất cả trạng thái</option>{Object.entries(statusName).map(([key, value]) => <option key={key} value={key}>{value}</option>)}</select></div>{error ? <ErrorBox error={error} /> : busy ? <Loading /> : filtered.length ? <div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>MÃ ĐƠN</th><th>KHÁCH HÀNG</th><th>NGÀY ĐẶT</th><th>TỔNG TIỀN</th><th>TRẠNG THÁI</th><th aria-label="Chi tiết" /></tr></thead><tbody>{filtered.map((order) => <tr key={order.id}><td><button className="admin-order-code" onClick={() => setSelectedId(order.id)}>{order.code}</button><small>{order.items.length} sản phẩm</small></td><td><strong>{order.customer_name}</strong><small>{order.phone}</small></td><td>{date(order.created_at)}</td><td><strong>{money(order.total)}</strong></td><td><StatusBadge status={order.status} /></td><td><button className="admin-row-link" onClick={() => setSelectedId(order.id)}>Chi tiết <ChevronRight size={16} /></button></td></tr>)}</tbody></table></div> : <Empty title="Chưa có đơn hàng phù hợp" detail={orders.length ? 'Thử đổi bộ lọc hoặc từ khóa tìm kiếm.' : 'Đơn hàng từ cửa hàng sẽ xuất hiện tại đây.'} />}<div className="admin-table-footer">Hiển thị {filtered.length} / {orders.length} đơn hàng</div></section>
    <AnimatePresence>{selected && <motion.div className="admin-modal-backdrop" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => { if (e.target === e.currentTarget) setSelectedId(null) }}><motion.div className="admin-modal admin-order-modal" initial={{ x: 32, opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: 32, opacity: 0 }}><button className="admin-modal-close" aria-label="Đóng" onClick={() => setSelectedId(null)}><X size={20} /></button><span className="admin-eyebrow">ORDER DETAILS</span><div className="admin-order-modal-head"><div><h2>{selected.code}</h2><p>Đặt ngày {date(selected.created_at)}</p></div><StatusBadge status={selected.status} /></div><div className="admin-order-detail-block"><h3>Thông tin khách hàng</h3><dl><div><dt>Họ và tên</dt><dd>{selected.customer_name}</dd></div><div><dt>Số điện thoại</dt><dd>{selected.phone}</dd></div><div><dt>Địa chỉ</dt><dd>{selected.address}</dd></div>{selected.notes && <div><dt>Ghi chú</dt><dd>{selected.notes}</dd></div>}</dl></div><div className="admin-order-detail-block"><h3>Sản phẩm</h3><div className="admin-order-items">{selected.items.map((item) => <div key={item.id} className="admin-order-item">{item.image_url ? <img src={item.image_url} alt="" /> : <span><Package size={18} /></span>}<div><strong>{item.product_name}</strong><small>{item.sku}{item.size ? ` · Size ${item.size}` : ''}{item.color ? ` · ${item.color}` : ''} · SL {item.quantity}</small></div><b>{money(item.line_total)}</b></div>)}</div><div className="admin-order-total"><span>Tổng cộng</span><strong>{money(selected.total)}</strong></div></div><div className="admin-order-detail-block"><h3>Cập nhật trạng thái</h3><div className="admin-status-update"><select aria-label="Trạng thái đơn hàng" value={selected.status} disabled={savingId === selected.id} onChange={(e) => changeStatus(selected, e.target.value as OrderStatus)}>{Object.entries(statusName).map(([key, value]) => <option key={key} value={key}>{value}</option>)}</select>{savingId === selected.id && <Loader2 size={18} className="admin-spin" />}</div></div></motion.div></motion.div>}</AnimatePresence></>
}

type CustomerView = { key: string; name: string; email: string; phone: string; address: string; type: 'registered' | 'guest'; created: string; orders: Order[] }
function CustomersPage() {
  const [profiles, setProfiles] = useState<Profile[]>([]); const [orders, setOrders] = useState<Order[]>([])
  const [busy, setBusy] = useState(true); const [error, setError] = useState(''); const [search, setSearch] = useState('')
  useEffect(() => { let live = true; Promise.all([listCustomers(), listOrders()]).then(([p, o]) => { if (live) { setProfiles(p); setOrders(o) } }).catch((err) => { if (live) setError(messageOf(err)) }).finally(() => { if (live) setBusy(false) }); return () => { live = false } }, [])
  const customers = useMemo(() => {
    const registered = profiles.filter((profile) => profile.role === 'customer').map((profile): CustomerView => ({ key: profile.id, name: profile.full_name || 'Khách hàng', email: profile.email || '', phone: profile.phone || '', address: profile.address || '', type: 'registered', created: profile.created_at, orders: orders.filter((order) => order.user_id === profile.id || Boolean(profile.phone && order.phone === profile.phone)) }))
    const phones = new Set(registered.map((item) => item.phone).filter(Boolean))
    const guests = new Map<string, CustomerView>()
    for (const order of orders) { if (order.user_id || phones.has(order.phone)) continue; const key = order.phone || order.customer_name; const found = guests.get(key); if (found) { found.orders.push(order); if (order.created_at < found.created) found.created = order.created_at } else guests.set(key, { key: `guest-${key}`, name: order.customer_name, email: '', phone: order.phone, address: order.address, type: 'guest', created: order.created_at, orders: [order] }) }
    return [...registered, ...guests.values()].sort((a, b) => b.created.localeCompare(a.created))
  }, [profiles, orders])
  const filtered = customers.filter((customer) => !search || `${customer.name} ${customer.email} ${customer.phone}`.toLowerCase().includes(search.toLowerCase()))
  return <><PageHead eyebrow="CUSTOMER RELATIONSHIPS" title="Khách hàng" description="Thông tin khách hàng và lịch sử mua sắm từ dữ liệu thực." /><div className="admin-inline-metrics"><span><strong>{customers.length}</strong> khách hàng</span><span><strong>{customers.filter((item) => item.type === 'registered').length}</strong> có tài khoản</span><span><strong>{customers.filter((item) => item.type === 'guest').length}</strong> mua không tài khoản</span></div><section className="admin-panel admin-table-panel"><div className="admin-filter-row"><div className="admin-search"><Search size={18} /><input aria-label="Tìm khách hàng" placeholder="Tìm tên, email hoặc số điện thoại..." value={search} onChange={(e) => setSearch(e.target.value)} /></div></div>{error ? <ErrorBox error={error} /> : busy ? <Loading /> : filtered.length ? <div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>KHÁCH HÀNG</th><th>LIÊN HỆ</th><th>LOẠI</th><th>ĐƠN HÀNG</th><th>CHI TIÊU</th><th>THAM GIA</th></tr></thead><tbody>{filtered.map((customer) => <tr key={customer.key}><td><div className="admin-customer-cell"><span>{customer.name.trim().charAt(0).toUpperCase() || 'K'}</span><div><strong>{customer.name}</strong><small>{customer.email || 'Không có email'}</small></div></div></td><td>{customer.phone || '—'}</td><td><span className={`admin-status ${customer.type === 'registered' ? 'stock-good' : 'product-draft'}`}>{customer.type === 'registered' ? 'Có tài khoản' : 'Khách vãng lai'}</span></td><td>{customer.orders.length}</td><td><strong>{money(customer.orders.filter((item) => item.status !== 'cancelled').reduce((sum, item) => sum + item.total, 0))}</strong></td><td>{date(customer.created)}</td></tr>)}</tbody></table></div> : <Empty title="Chưa có khách hàng phù hợp" detail={customers.length ? 'Thử từ khóa tìm kiếm khác.' : 'Khách hàng sẽ xuất hiện khi có tài khoản hoặc đơn hàng.'} />}<div className="admin-table-footer">Hiển thị {filtered.length} / {customers.length} khách hàng</div></section></>
}

function SettingsPage() {
  const toast = useToast(); const [settings, setSettings] = useState<SiteSettings>({}); const [banners, setBanners] = useState<Banner[]>([])
  const [busy, setBusy] = useState(true); const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  const [heroFile, setHeroFile] = useState<File | null>(null); const [heroPreview, setHeroPreview] = useState('')
  const [bannerOpen, setBannerOpen] = useState(false); const [editingBanner, setEditingBanner] = useState<Banner | null>(null)
  const [bannerForm, setBannerForm] = useState<BannerInput>({ title: '', image_url: '', subtitle: '', eyebrow: '', link_url: '/san-pham-moi', link_label: 'Khám phá', is_active: true, sort_order: 0 })
  const [bannerFile, setBannerFile] = useState<File | null>(null); const [bannerPreview, setBannerPreview] = useState(''); const [bannerSaving, setBannerSaving] = useState(false)
  useEffect(() => { let live = true; Promise.all([getSiteSettings(), adminListBanners()]).then(([s, b]) => { if (live) { setSettings(s); setBanners(b) } }).catch((err) => { if (live) setError(messageOf(err)) }).finally(() => { if (live) setBusy(false) }); return () => { live = false } }, [])
  const get = (key: string) => String(settings[key] ?? '')
  const set = (key: string, value: string) => setSettings((current) => ({ ...current, [key]: value }))
  async function saveContent(event: FormEvent) { event.preventDefault(); setSaving(true); try { const next = heroFile ? { ...settings, hero_image_url: await uploadBannerImage(heroFile) } : settings; await saveSiteSettings(next); setSettings(next); setHeroFile(null); setHeroPreview(''); toast('Đã cập nhật nội dung website.') } catch (err) { toast(messageOf(err), 'error') } finally { setSaving(false) } }
  function chooseHeroImage(file?: File) { if (!file) return; if (!file.type.startsWith('image/')) { toast('Vui lòng chọn tệp hình ảnh.', 'error'); return }; setHeroFile(file); const reader = new FileReader(); reader.onload = () => setHeroPreview(String(reader.result)); reader.readAsDataURL(file) }
  function showBanner(banner?: Banner) { setEditingBanner(banner || null); setBannerForm(banner ? { title: banner.title, subtitle: banner.subtitle, eyebrow: banner.eyebrow, image_url: banner.image_url, link_url: banner.link_url, link_label: banner.link_label, is_active: banner.is_active, sort_order: banner.sort_order } : { title: '', image_url: '', subtitle: '', eyebrow: '', link_url: '/san-pham-moi', link_label: 'Khám phá', is_active: true, sort_order: banners.length }); setBannerFile(null); setBannerPreview(''); setBannerOpen(true) }
  function chooseBannerImage(file?: File) { if (!file) return; if (!file.type.startsWith('image/')) { toast('Vui lòng chọn tệp hình ảnh.', 'error'); return }; setBannerFile(file); const reader = new FileReader(); reader.onload = () => setBannerPreview(String(reader.result)); reader.readAsDataURL(file) }
  async function submitBanner(event: FormEvent) { event.preventDefault(); if (!bannerFile && !bannerForm.image_url) { toast('Vui lòng chọn ảnh banner.', 'error'); return }; setBannerSaving(true); try { const image_url = bannerFile ? await uploadBannerImage(bannerFile) : bannerForm.image_url; const result = await saveBanner({ ...bannerForm, image_url }, editingBanner?.id); setBanners((current) => [...current.filter((item) => item.id !== result.id), result].sort((a, b) => a.sort_order - b.sort_order)); toast(editingBanner ? 'Đã cập nhật banner.' : 'Đã thêm banner.'); setBannerOpen(false) } catch (err) { toast(messageOf(err), 'error') } finally { setBannerSaving(false) } }
  async function removeBanner(banner: Banner) { if (!window.confirm(`Xóa banner “${banner.title}”?`)) return; try { await deleteBanner(banner.id); setBanners((current) => current.filter((item) => item.id !== banner.id)); toast('Đã xóa banner.') } catch (err) { toast(messageOf(err), 'error') } }
  async function toggleBanner(banner: Banner) { try { const updated = await saveBanner({ title: banner.title, image_url: banner.image_url, subtitle: banner.subtitle, eyebrow: banner.eyebrow, link_url: banner.link_url, link_label: banner.link_label, sort_order: banner.sort_order, is_active: !banner.is_active }, banner.id); setBanners((current) => current.map((item) => item.id === banner.id ? updated : item)); toast(updated.is_active ? 'Đã hiển thị banner.' : 'Đã ẩn banner.') } catch (err) { toast(messageOf(err), 'error') } }
  return <><PageHead eyebrow="YOUR BRAND STORY" title="Website & banner" description="Giữ nội dung cửa hàng luôn mới, luôn đúng tinh thần MUSE." />{error ? <ErrorBox error={error} /> : busy ? <Loading /> : <><div className="admin-settings-grid"><form className="admin-panel admin-form-section admin-settings-form" onSubmit={saveContent}><div className="admin-form-section-title"><span>01</span><div><h2>Nội dung website</h2><p>Cập nhật lời giới thiệu và thông điệp trên trang chủ.</p></div></div><Field label="Thông báo đầu trang"><input value={get('announcement_text')} onChange={(e) => set('announcement_text', e.target.value)} placeholder="Miễn phí vận chuyển cho đơn từ 1.000.000đ" /></Field><div className="admin-settings-subhead">HERO SECTION</div><Field label="Ảnh chính"><label className="admin-banner-upload" title="Nhấn để thay ảnh hero"><img src={heroPreview || get('hero_image_url') || '/hero-editorial.png'} alt="Ảnh hero hiện tại" /><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(e) => chooseHeroImage(e.target.files?.[0])} /></label><small>Nhấn vào ảnh để thay đổi. JPG, PNG, WebP hoặc AVIF, tối đa 10 MB.</small></Field><Field label="Tiêu đề chính"><input value={get('hero_title')} onChange={(e) => set('hero_title', e.target.value)} placeholder="A new expression of you" /></Field><Field label="Mô tả hero"><textarea rows={3} value={get('hero_subtitle')} onChange={(e) => set('hero_subtitle', e.target.value)} placeholder="Phong cách riêng, câu chuyện riêng..." /></Field><div className="admin-settings-subhead">CÂU CHUYỆN THƯƠNG HIỆU</div><Field label="Tiêu đề giới thiệu"><input value={get('about_title')} onChange={(e) => set('about_title', e.target.value)} placeholder="Đẹp theo cách của bạn" /></Field><Field label="Nội dung giới thiệu"><textarea rows={5} value={get('about_body')} onChange={(e) => set('about_body', e.target.value)} placeholder="MUSE STORE là nơi..." /></Field><div className="admin-settings-subhead">KHI KHÔNG CÓ BANNER QUẢNG BÁ</div><Field label="Tiêu đề dự phòng"><input value={get('promo_title')} onChange={(e) => set('promo_title', e.target.value)} placeholder="A moment for you" /></Field><Field label="Nội dung dự phòng"><textarea rows={3} value={get('promo_body')} onChange={(e) => set('promo_body', e.target.value)} /></Field><Field label="Liên kết dự phòng"><input value={get('promo_link')} onChange={(e) => set('promo_link', e.target.value)} placeholder="/sale" /></Field><div className="admin-settings-save"><button className="admin-button admin-button-dark" type="submit" disabled={saving}>{saving ? <Loader2 size={16} className="admin-spin" /> : <Save size={16} />} Lưu nội dung</button></div></form><div className="admin-settings-aside"><section className="admin-panel admin-banner-panel"><div className="admin-section-head"><div><span className="admin-eyebrow">VISUAL STORYTELLING</span><h2>Banner quảng bá</h2></div><button className="admin-icon-button" onClick={() => showBanner()} title="Thêm banner"><Plus size={20} /></button></div><p>Banner đang bật có thứ tự thấp nhất sẽ hiển thị trên trang chủ.</p>{banners.length ? <div className="admin-banner-list">{banners.map((banner) => <div className="admin-banner-row" key={banner.id}><img src={banner.image_url} alt="" /><div><strong>{banner.title}</strong><small>{banner.eyebrow || 'BANNER'} · {banner.is_active ? 'Đang hiển thị' : 'Đã ẩn'}</small></div><div className="admin-banner-actions"><button onClick={() => showBanner(banner)} title="Chỉnh sửa"><Pencil size={16} /></button><button onClick={() => toggleBanner(banner)} title={banner.is_active ? 'Ẩn' : 'Hiện'}>{banner.is_active ? <EyeOff size={16} /> : <Eye size={16} />}</button><button onClick={() => removeBanner(banner)} className="danger" title="Xóa"><Trash2 size={16} /></button></div></div>)}</div> : <Empty title="Chưa có banner" detail="Thêm hình ảnh đầu tiên cho trang chủ." action={<button className="admin-button admin-button-light" onClick={() => showBanner()}><Plus size={16} /> Thêm banner</button>} />}</section><div className="admin-settings-note"><Sparkles size={20} /><div><strong>Một câu chuyện nhất quán</strong><p>Nội dung sau khi lưu sẽ được lấy từ cơ sở dữ liệu và hiển thị trên cửa hàng.</p></div></div></div></div></>}
    <AnimatePresence>{bannerOpen && <motion.div className="admin-modal-backdrop" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={(e) => { if (e.target === e.currentTarget) setBannerOpen(false) }}><motion.div className="admin-modal admin-form-modal" initial={{ scale: .96, y: 15 }} animate={{ scale: 1, y: 0 }} exit={{ scale: .96, y: 15 }}><button className="admin-modal-close" onClick={() => setBannerOpen(false)} aria-label="Đóng"><X size={20} /></button><span className="admin-eyebrow">HOMEPAGE BANNER</span><h2>{editingBanner ? 'Chỉnh sửa banner' : 'Thêm banner mới'}</h2><form onSubmit={submitBanner}><Field label="Hình ảnh banner *"><label className="admin-banner-upload">{bannerPreview || bannerForm.image_url ? <img src={bannerPreview || bannerForm.image_url} alt="Xem trước banner" /> : <span><ImagePlus size={28} /> Nhấn để chọn ảnh</span>}<input type="file" accept="image/*" onChange={(e) => chooseBannerImage(e.target.files?.[0])} /></label></Field><div className="admin-fields-grid"><Field label="Tiêu đề *"><input required value={bannerForm.title} onChange={(e) => setBannerForm((current) => ({ ...current, title: e.target.value }))} placeholder="The art of becoming" /></Field><Field label="Dòng nhỏ"><input value={bannerForm.eyebrow || ''} onChange={(e) => setBannerForm((current) => ({ ...current, eyebrow: e.target.value }))} placeholder="MUSE COLLECTION" /></Field></div><Field label="Mô tả"><textarea rows={3} value={bannerForm.subtitle || ''} onChange={(e) => setBannerForm((current) => ({ ...current, subtitle: e.target.value }))} /></Field><div className="admin-fields-grid"><Field label="Nhãn nút"><input value={bannerForm.link_label || ''} onChange={(e) => setBannerForm((current) => ({ ...current, link_label: e.target.value }))} placeholder="Khám phá" /></Field><Field label="Liên kết"><input value={bannerForm.link_url || ''} onChange={(e) => setBannerForm((current) => ({ ...current, link_url: e.target.value }))} placeholder="/san-pham-moi" /></Field><Field label="Thứ tự"><input type="number" min="0" value={bannerForm.sort_order ?? 0} onChange={(e) => setBannerForm((current) => ({ ...current, sort_order: Number(e.target.value) }))} /></Field><Field label="Hiển thị"><select value={bannerForm.is_active ? 'yes' : 'no'} onChange={(e) => setBannerForm((current) => ({ ...current, is_active: e.target.value === 'yes' }))}><option value="yes">Đang hiển thị</option><option value="no">Ẩn</option></select></Field></div><div className="admin-modal-actions"><button className="admin-button admin-button-light" type="button" onClick={() => setBannerOpen(false)}>Hủy</button><button className="admin-button admin-button-dark" type="submit" disabled={bannerSaving}>{bannerSaving ? <Loader2 size={16} className="admin-spin" /> : <Save size={16} />} Lưu banner</button></div></form></motion.div></motion.div>}</AnimatePresence></>
}

export default function AdminApp() {
  return <MotionConfig reducedMotion="user"><ToastProvider><Routes><Route path="login" element={<LoginPage />} /><Route element={<AdminGate />}><Route element={<AdminLayout />}><Route index element={<DashboardPage />} /><Route path="products" element={<ProductsPage />} /><Route path="products/new" element={<ProductFormPage />} /><Route path="products/:id/edit" element={<ProductFormPage />} /><Route path="categories" element={<CategoriesPage />} /><Route path="inventory" element={<InventoryPage />} /><Route path="orders" element={<OrdersPage />} /><Route path="customers" element={<CustomersPage />} /><Route path="settings" element={<SettingsPage />} /></Route></Route><Route path="*" element={<Navigate to="/admin" replace />} /></Routes></ToastProvider></MotionConfig>
}
